import{_ as t,o as r,c as o,a5 as a}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"Coloured-Stone Grading","description":"","frontmatter":{"title":"Coloured-Stone Grading","grading":"colored-stones"},"headers":[],"relativePath":"grading/colored-stones.md","filePath":"grading/colored-stones.md","lastUpdated":1789230763000}'),i={name:"grading/colored-stones.md"};function d(n,e,l,s,h,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="coloured-stone-grading" tabindex="-1">Coloured-Stone Grading <a class="header-anchor" href="#coloured-stone-grading" aria-label="Permalink to &quot;Coloured-Stone Grading&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Coloured gems lack a single 4C scheme. Instead, colour is graded on three axes—hue (position on the colour wheel), tone (lightness), and saturation (intensity). Many laboratories use these descriptive dimensions, but report terms and thresholds can differ.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Hue: position on the colour wheel. Top stones are close to a pure hue.</li><li>Tone: lightness in 6 grades (very light → very dark); best in medium / medium-light.</li><li>Saturation: vividness. Browns and greys depress value; vivid / strong is best.</li><li>Colour is often important, but cut, clarity, durability, treatment, and supply also affect value.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Grade</th><th>Note</th></tr></thead><tbody><tr><td>ruby</td><td>vivid red, medium tone</td><td>pigeon-blood red</td></tr><tr><td>emerald</td><td>vivid green, slightly bluish</td><td>top Muzo / Chivor</td></tr><tr><td>sapphire</td><td>vivid blue, medium-dark</td><td>royal / cornflower</td></tr></tbody></table><p><em>See the <a href="./intro.html">grading overview</a>.</em></p>',8)])])}const m=t(i,[["render",d]]);export{p as __pageData,m as default};
